package com.procurement.quotationcomparison.mapper;import com.procurement.quotationcomparison.dto.response.*;import com.procurement.quotationcomparison.entity.*;import org.springframework.stereotype.Component;@Component public class QuotationComparisonMapper{public QuotationComparisonResponse comparison(QuotationComparison e){return new QuotationComparisonResponse(e.getId(),e.getComparisonNumber(),e.getRfq().getId(),e.getRfq().getRfqNumber(),e.getComparisonMethod(),e.getComparisonDate(),e.getPreparedBy(),e.getApprovedBy(),e.getStatus(),e.getRemarks());}public QuotationComparisonLineResponse line(QuotationComparisonLine e){return new QuotationComparisonLineResponse(e.getId(),e.getComparison().getId(),e.getVendorQuotation().getId(),e.getVendor().getId(),e.getVendor().getVendorName(),e.getPriceScore(),e.getTechnicalScore(),e.getQualityScore(),e.getDeliveryScore(),e.getWarrantyScore(),e.getCommercialScore(),e.getOverallScore(),e.getRank(),e.getRecommended());}}
